  const historicalMatches=applyHistory?data.statements.flatMap(s=>s.transactions.filter(t=>t.type==='purchase'&&!selected.has(`${s.id}::${t.id}`)&&t.categorySource!=='manual'&&t.source!=='manual'&&rules.some(rule=>matchesMerchantRule(rule,s.cardId,t))).map(tx=>({statement:s,tx,rule:rules.find(rule=>matchesMerchantRule(rule,s.cardId,tx))!}))):[];
